/**
 * 道德选择事件 — 随机遭遇 + 后续后果链
 *
 * 每触发一个事件，玩家在2-3个选项中做选择 → 设置moral flag →
 * 一定天数后触发对应的后续后果事件。
 */

// ====== 道德事件定义 ======
const MORAL_EVENTS = [
  // ─── 1. 捡到钱包 ───
  {
    id: "found_wallet",
    title: "👛 路边捡到一个钱包",
    desc: "你在地上发现一个鼓鼓的钱包，里面有身份证、银行卡和一厚叠现金（约¥500）。四周无人注意到你。",
    minDay: 3,
    dailyChance: 0.04,
    choices: [
      {
        text: "📩 送到最近的派出所归还失主",
        flag: "moral_wallet_return",
        score: 12,
        immediate: (s) => {
          s.status.fame = Math.min(100, (s.status.fame || 0) + 2);
          s.needs.happiness = Math.min(100, s.needs.happiness + 5);
          StateManager.addMessage(
            "👮 警察登记了你的信息，说失主会联系你。心里很踏实。",
            "success",
          );
        },
      },
      {
        text: "💰 看看四周没人，收进自己口袋",
        flag: "moral_wallet_keep",
        score: -15,
        immediate: (s) => {
          s.resources.cash += 500;
          s.needs.happiness = Math.min(100, s.needs.happiness + 8);
          StateManager.addMessage(
            "💵 你快速把钱塞进口袋，心跳加速地离开了现场。",
            "warning",
          );
        },
      },
      {
        text: "📸 拍照发朋友圈炫耀('今日好运')，钱留下",
        flag: "moral_wallet_flaunt",
        score: -10,
        immediate: (s) => {
          s.resources.cash += 500;
          s.status.fame = Math.min(100, (s.status.fame || 0) + 5);
          s.needs.happiness = Math.min(100, s.needs.happiness + 10);
          StateManager.addMessage(
            "📱 朋友圈炸了，但你隐约觉得不太妥当...",
            "event",
          );
        },
      },
    ],
  },

  // ─── 2. 遇到乞丐 ───
  {
    id: "beggar_ask",
    title: "🧓 路边的老乞丐",
    desc: "一个衣衫褴褛的老人坐在路边，面前放着破碗，颤抖着向你伸出手。他已经一整天没吃东西了。",
    minDay: 5,
    dailyChance: 0.05,
    choices: [
      {
        text: "🍞 去旁边买份盒饭给他",
        flag: "moral_beggar_feed",
        score: 8,
        immediate: (s) => {
          s.resources.cash -= 15;
          s.needs.happiness = Math.min(100, s.needs.happiness + 6);
          StateManager.addMessage(
            "🎭 老人眼眶湿润，连声道谢。周围人向你投来赞许的目光。",
            "success",
          );
        },
      },
      {
        text: "🪙 扔几个硬币打发一下",
        flag: "moral_beggar_coin",
        score: 3,
        immediate: (s) => {
          s.resources.cash -= 2;
          s.needs.happiness = Math.min(100, Math.max(0, s.needs.happiness - 1));
          StateManager.addMessage(
            "🪙 硬币叮当落入碗中，你没有多看一眼。",
            "info",
          );
        },
      },
      {
        text: "🚶 装作没看见快步走过",
        flag: "moral_beggar_ignore",
        score: -3,
        immediate: (s) => {
          s.needs.happiness = Math.max(0, s.needs.happiness - 2);
          StateManager.addMessage(
            "😐 你低下头走开了，但心里有些不舒服。",
            "info",
          );
        },
      },
      {
        text: "👎 嫌恶地绕到马路对面",
        flag: "moral_beggar_despise",
        score: -8,
        immediate: (s) => {
          s.needs.happiness = Math.max(0, s.needs.happiness - 4);
          StateManager.addMessage(
            "😤 老人看到你的反应，默默地收回了手。",
            "warning",
          );
        },
      },
    ],
  },

  // ─── 3. 商店多找钱 ───
  {
    id: "change_overpaid",
    title: "🧾 商店多找了钱",
    desc: "在小卖部买东西时，老板多找了¥20。他正忙着招呼其它顾客，完全没注意到。",
    minDay: 2,
    dailyChance: 0.04,
    choices: [
      {
        text: "✅ 立刻退还多找的钱",
        flag: "moral_change_return",
        score: 8,
        immediate: (s) => {
          s.needs.happiness = Math.min(100, s.needs.happiness + 3);
          StateManager.addMessage(
            "👴 老板愣了一下，感激地对你笑了笑。",
            "success",
          );
        },
      },
      {
        text: "😶 默不作声地收进口袋",
        flag: "moral_change_keep",
        score: -8,
        immediate: (s) => {
          s.resources.cash += 20;
          s.needs.happiness = Math.min(100, Math.max(0, s.needs.happiness - 1));
          StateManager.addMessage("💵 你快速离开小店，¥20到手。", "info");
        },
      },
    ],
  },

  // ─── 4. 目击小偷 ───
  {
    id: "see_pickpocket",
    title: "👀 目击扒手行窃",
    desc: "你在人群中发现一个扒手正在悄悄拉开前面女士的背包拉链！他的眼神凶狠，似乎是个惯犯。",
    minDay: 7,
    dailyChance: 0.03,
    choices: [
      {
        text: "🔔 大声提醒「有小偷！」",
        flag: "moral_stop_thief",
        score: 15,
        immediate: (s) => {
          s.status.fame = Math.min(100, (s.status.fame || 0) + 5);
          s.needs.happiness = Math.min(100, s.needs.happiness + 8);
          s.status.health = Math.max(0, s.status.health - 2); // 可能挨打
          StateManager.addMessage(
            "🗣️ 女士反应过来，扒手瞪了你一眼后混入人群跑了。周围人纷纷称赞你。",
            "success",
          );
        },
      },
      {
        text: "📱 偷偷拍下照片事后交给警察",
        flag: "moral_thief_photo",
        score: 10,
        immediate: (s) => {
          s.status.fame = Math.min(100, (s.status.fame || 0) + 3);
          StateManager.addMessage(
            "📸 你拍到了扒手的正脸，快步走向附近的派出所。",
            "info",
          );
        },
      },
      {
        text: "🙈 假装没看见，低头玩手机",
        flag: "moral_thief_ignore",
        score: -10,
        immediate: (s) => {
          s.needs.happiness = Math.max(0, s.needs.happiness - 5);
          StateManager.addMessage(
            "😰 你听到身后传来「我的手机呢！」的惊呼，心里一阵愧疚。",
            "warning",
          );
        },
      },
    ],
  },

  // ─── 5. 摆摊缺斤短两的诱惑 ───
  {
    id: "scam_customers",
    title: "⚖️ 秤上做手脚？",
    desc: "摆摊时，隔壁摊主悄悄告诉你一个「秘诀」：把电子秤调偏5%，一天能多赚好几十块。今天生意不太好的话...",
    minDay: 10,
    dailyChance: 0.03,
    condition: (s) => s.trade.currentLocation === "commercialDist",
    choices: [
      {
        text: "✅ 堂堂正正做生意，拒绝调秤",
        flag: "moral_honest_scale",
        score: 10,
        immediate: (s) => {
          s.needs.happiness = Math.min(100, s.needs.happiness + 2);
          StateManager.addMessage(
            "⚖️ 你坚持给了足斤足两。顾客露出满意的笑容。",
            "success",
          );
        },
      },
      {
        text: "⚙️ 偷偷调偏5%，多赚一点是一点",
        flag: "moral_rig_scale",
        score: -12,
        immediate: (s) => {
          StateManager.addMessage(
            "🔧 你调了秤...今天确实多赚了，但总觉得有人在盯着你。",
            "warning",
          );
        },
      },
    ],
  },

  // ─── 6. 捡到手机 ───
  {
    id: "found_phone",
    title: "📱 捡到一部最新款手机",
    desc: "公共厕所的洗手台上放着一部崭新的最新款手机，价值至少¥3000，没有锁屏密码。",
    minDay: 8,
    dailyChance: 0.03,
    choices: [
      {
        text: "📞 翻通讯录联系失主家人归还",
        flag: "moral_phone_return",
        score: 12,
        immediate: (s) => {
          s.needs.happiness = Math.min(100, s.needs.happiness + 5);
          s.status.fame = Math.min(100, (s.status.fame || 0) + 3);
          StateManager.addMessage(
            "📞 失主是个学生，差点哭出来，非要请你吃饭。",
            "success",
          );
        },
      },
      {
        text: "💸 拿去二手店卖掉换钱",
        flag: "moral_phone_sell",
        score: -12,
        immediate: (s) => {
          s.resources.cash += 1500;
          s.needs.happiness = Math.min(100, s.needs.happiness + 5);
          StateManager.addMessage(
            "💰 二手店老板狐疑地看了你一眼，还是收了。你快步离开。",
            "warning",
          );
        },
      },
    ],
  },

  // ─── 7. 下雨天流浪狗 ───
  {
    id: "stray_dog_rain",
    title: "🐕 雨中的流浪狗",
    desc: "大雨中，一只瑟瑟发抖的流浪狗蜷缩在屋檐下，用湿漉漉的眼睛看着你。它看起来很虚弱。",
    minDay: 4,
    dailyChance: 0.04,
    condition: (s) =>
      s.weather &&
      (s.weather.weatherId === "heavy_rain" ||
        s.weather.weatherId === "thunderstorm"),
    choices: [
      {
        text: "🍖 买根火腿肠喂它，引到避雨处",
        flag: "moral_dog_feed",
        score: 8,
        immediate: (s) => {
          s.resources.cash -= 3;
          s.needs.happiness = Math.min(100, s.needs.happiness + 8);
          StateManager.addMessage(
            "🐕 小狗狼吞虎咽地吃完，舔了舔你的手，摇着尾巴跟了一段路。",
            "success",
          );
        },
      },
      {
        text: "😔 叹息一声，转身走了",
        flag: "moral_dog_ignore",
        score: 0,
        immediate: (s) => {
          s.needs.happiness = Math.max(0, s.needs.happiness - 2);
          StateManager.addMessage(
            "🌧️ 身后传来低低的呜咽声，被雨声盖过了。",
            "info",
          );
        },
      },
    ],
  },

  // ─── 8. 老人跌倒 ───
  {
    id: "old_fall",
    title: "👴 老人摔倒了",
    desc: "前面一个老人突然踉跄了一下，摔倒在路边。他挣扎着想爬起来，但似乎扭伤了脚。周围人都在看，没人上前。",
    minDay: 10,
    dailyChance: 0.025,
    choices: [
      {
        text: "🏃 快步上前扶起老人",
        flag: "moral_help_fallen",
        score: 15,
        immediate: (s) => {
          s.needs.happiness = Math.min(100, s.needs.happiness + 6);
          s.status.fame = Math.min(100, (s.status.fame || 0) + 4);
          StateManager.addMessage(
            "👴 老人连声道谢，说自己有儿女在国外，平时很少人帮忙。",
            "success",
          );
        },
      },
      {
        text: "📹 站远点拍视频发到网上@官方账号",
        flag: "moral_fall_video",
        score: -2,
        immediate: (s) => {
          s.status.fame = Math.min(100, (s.status.fame || 0) + 8);
          s.needs.happiness = Math.max(0, s.needs.happiness - 1);
          StateManager.addMessage(
            "📱 视频获得不少点赞，但你知道自己没真的帮忙。",
            "event",
          );
        },
      },
      {
        text: "😰 怕被讹诈，低头快步走开",
        flag: "moral_fall_ignore",
        score: -10,
        immediate: (s) => {
          s.needs.happiness = Math.max(0, s.needs.happiness - 6);
          StateManager.addMessage(
            "😞 你走出几步，回头看到另一个路人上前帮忙了。",
            "warning",
          );
        },
      },
    ],
  },

  // ─── 9. 共享单车损坏 ───
  {
    id: "bike_broken",
    title: "🚲 路边损坏的共享单车",
    desc: "你在路边看到一辆共享单车的二维码被刮花了，车锁也被撬坏。四周无人。如果你会修的话，可以修好它。",
    minDay: 6,
    dailyChance: 0.035,
    choices: [
      {
        text: "🔧 花点时间修好并上报",
        flag: "moral_bike_fix",
        score: 6,
        immediate: (s) => {
          if (s.skills.repair)
            s.skills.repair.xp = Math.min(1000, (s.skills.repair.xp || 0) + 20);
          s.needs.happiness = Math.min(100, s.needs.happiness + 3);
          StateManager.addMessage(
            "🔧 修好后又骑到指定停放点，给下一个人用。感觉不错。",
            "success",
          );
        },
