// ====== 触发逻辑 ======

/**
 * 随机触发一个道德事件（在时段转换时调用）
 * 返回 true 表示触发了，false 表示未触发
 */
function triggerMoralEvent(state) {
  // 排除已触发的（同一天不重复触发）
  const todayActions = (state.flags.moral.actions || []).filter(
    (a) => a.day === state.player.day,
  );
  if (todayActions.length > 0) return false;

  // 捡到钱包后不再触发严苛度高的拾取事件
  const hasWalletAction = (state.flags.moral.actions || []).some(
    (a) => a.id === "found_wallet",
  );

  const eligible = MORAL_EVENTS.filter((evt) => {
    if (evt.minDay && state.player.day < evt.minDay) return false;
    if (evt.condition && !evt.condition(state)) return false;
    // 同一事件不重复触发
    if ((state.flags.moral.actions || []).some((a) => a.id === evt.id))
      return false;
    // 捡到手机/钱包后不再触发类似事件
    if (
      hasWalletAction &&
      (evt.id === "found_phone" || evt.id === "found_wallet")
    )
      return false;
    return true;
  });

  if (eligible.length === 0) return false;

  // 随机选一个事件
  const evt = Random.fromArray(eligible);
  if (!Random.chance(evt.dailyChance)) return false;

  // 构建choice回调
  const choiceActions = evt.choices.map((choice) => ({
    text: choice.text,
    cls: "btn-primary",
    callback: () => {
      const s = StateManager.getState();
      // 记录道德action
      if (!s.flags.moral.actions) s.flags.moral.actions = [];
      s.flags.moral.actions.push({
        id: evt.id,
        choice: choice.flag,
        score: choice.score,
        day: s.player.day,
      });
      // 更新道德总分
      s.flags.moral.score = Math.max(
        -100,
        Math.min(100, (s.flags.moral.score || 0) + choice.score),
      );
      // 立即效果
      if (choice.immediate) choice.immediate(s);
      // 如果有后续后果，加入待执行队列
      const consequence = MORAL_CONSEQUENCES[choice.flag];
      if (consequence) {
        if (!s.flags.moral.pendingConsequences)
          s.flags.moral.pendingConsequences = [];
        const delay = Random.int(consequence.delay[0], consequence.delay[1]);
        s.flags.moral.pendingConsequences.push({
          eventId: consequence.id,
          actionId: choice.flag,
          dueDay: s.player.day + delay,
        });
      }
      renderAll();
    },
  }));

  // 使用showModal展示选择
  showModal({
    title: evt.title,
    body: `<p style="line-height:1.7;">${evt.desc}</p>`,
    buttons: choiceActions,
  });

  return true;
}

/**
 * 每日检查并触发待处理的道德后果（在endDay中调用）
 */
function checkMoralConsequences(state) {
  const pending = state.flags.moral.pendingConsequences;
  if (!pending || pending.length === 0) return;

  const due = pending.filter((c) => c.dueDay <= state.player.day);
  if (due.length === 0) return;

  // 从pending中移除已到期的
  state.flags.moral.pendingConsequences = pending.filter(
    (c) => c.dueDay > state.player.day,
  );

  for (const con of due) {
    // 找到对应action
    const action = (state.flags.moral.actions || []).find(
      (a) => a.choice === con.actionId,
    );
    if (!action) continue; // 不应该发生

    const consequenceDef = MORAL_CONSEQUENCES[con.actionId];
    if (!consequenceDef) continue;

    // 显示后续事件弹窗
    const descText =
      typeof consequenceDef.desc === "function"
        ? consequenceDef.desc(state)
        : consequenceDef.desc;

    showModal({
      title: consequenceDef.title,
      body: `<p style="line-height:1.7;">${descText}</p>`,
      buttons: [
        {
          text: "知道了",
          cls: "btn-primary",
          callback: () => {
            const s2 = StateManager.getState();
            consequenceDef.apply(s2);
            renderAll();
          },
        },
      ],
    });
  }
}

/**
 * 获取道德等级中文描述
 */
function getMoralLevelName(score) {
  if (score >= 80) return "圣贤";
  if (score >= 50) return "善良";
  if (score >= 20) return "正直";
  if (score >= -10) return "普通人";
  if (score >= -40) return "自私";
  if (score >= -70) return "冷漠";
  return "堕入黑暗";
}

/**
 * 获取道德等级对应的emoji
 */
function getMoralEmoji(score) {
  if (score >= 50) return "😇";
  if (score >= 20) return "👍";
  if (score >= -10) return "😐";
  if (score >= -40) return "😒";
  return "👿";
}

