461	/** 雇佣运输——将指定商品从当前地点运到目标地点 */
462	function hireTransport(serviceId, goods, destKey) {
463	  const state = StateManager.getState();
464	  const service = getTransportService(serviceId);
465	  if (!service) {
466	    StateManager.addMessage("⚠️ 不存在的运输服务。", "danger");
467	    return false;
468	  }
469	
470	  // 检查目标地点是否可达
471	  const reachable = getReachableLocations(state.trade.currentLocation);
472	  if (!reachable.includes(destKey)) {
473	    StateManager.addMessage("⚠️ 该地点无法直接到达。", "danger");
474	    return false;
475	  }
476	
477	  // 计算运费
478	  let totalQty = 0;
479	  let totalWeight = 0;
480	  let totalVolume = 0;
481	  let totalValue = 0;
482	  const toShip = []; // { id, qty, good }
483	
484	  for (const { goodId, qty } of goods) {
485	    const good = getGoodById(goodId);
486	    if (!good) continue;
487	    const inv = state.inventory.items.find((i) => i.id === goodId);
488	    if (!inv || inv.qty < qty) {
489	      StateManager.addMessage(`⚠️ 背包中${good.name}不足。`, "danger");
490	      return false;
491	    }
492	    const phys = getGoodPhysics(goodId);
493	    totalQty += qty;
494	    totalWeight += phys.weight * qty;
495	    totalVolume += phys.volume * qty;
496	    const price = getCurrentPrice(state.trade.currentLocation, goodId);
497	    totalValue += price * qty;
498	    toShip.push({ id: goodId, qty, good });
499	  }
500	
501	  if (totalQty === 0) {
502	    StateManager.addMessage("⚠️ 没有需要运输的货物。", "danger");
503	    return false;
504	  }
505	
506	  // 检查运输容量
507	  if (totalWeight > service.capacity || totalVolume > service.volumeCapacity) {
508	    StateManager.addMessage(
509	      `⚠️ ${service.name}装不下这么多货物！重量${Math.round(totalWeight)}/${service.capacity}，体积${Math.round(totalVolume)}/${service.volumeCapacity}`,
510	      "danger",
511	    );
512	    return false;
513	  }
514	
515	  // 检查现金
516	  if (state.resources.cash < service.cost) {
517	    StateManager.addMessage(`⚠️ 运费¥${service.cost}，现金不足。`, "danger");
518	    return false;
519	  }
520	
521	  // 消耗AP
522	  if (!consumeAP(AP_COSTS.check_investment)) return false;
523	
524	  // 扣运费
525	  state.resources.cash -= service.cost;
526	
527	  // 从背包中移除货物
528	  for (const { id, qty } of toShip) {
529	    const inv = state.inventory.items.find((i) => i.id === id);
530	    inv.qty -= qty;
531	    if (inv.qty <= 0) {
532	      state.inventory.items = state.inventory.items.filter((i) => i.id !== id);
533	    }
534	  }
535	
536	  // 运输随机事件
537	  let events = [];
538	
539	  // 1. 偷窃事件
540	  if (Random.chance(service.theftRisk / 100)) {
541	    // 随机偷走10-30%的某一种货物
542	    const targetGood = Random.fromArray(toShip);
543	    const stolenRatio = Random.float(0.1, 0.3);
544	    const stolenQty = Math.max(1, Math.floor(targetGood.qty * stolenRatio));
545	    targetGood.qty -= stolenQty;
546	    const good = getGoodById(targetGood.id);
547	    events.push(
548	      `🦹 ${service.name}偷了${stolenQty}${good.unit}${good.name}！损失约¥${Math.round(getCurrentPrice(state.trade.currentLocation, targetGood.id) * stolenQty)}`,
549	    );
550	    state.needs.happiness = Math.max(0, state.needs.happiness - 8);
551	  }
552	
553	  // 2. 货物损坏事件
554	  if (Random.chance(service.damageRisk / 100)) {
555	    // 随机损坏易碎/温敏货物
556	    const fragileGoods = toShip.filter((g) => {
557	      const phys = getGoodPhysics(g.id);
558	      return phys.fragile || phys.tempSensitive;
559	    });
560	    if (fragileGoods.length > 0) {
561	      const target = Random.fromArray(fragileGoods);
562	      const damagedQty = Math.max(
563	        1,
564	        Math.floor(target.qty * service.damageRatio),
565	      );
566	      target.qty -= damagedQty;
567	      const good = getGoodById(target.id);
568	      events.push(`💔 运输途中损坏了${damagedQty}${good.unit}${good.name}。`);
569	    }
570	  }
571	
572	  // 3. 交通意外（2%概率，不论什么运输方式）
573	  if (Random.chance(0.02)) {
574	    const accidentLoss = Math.floor(totalQty * 0.15);
575	    if (accidentLoss > 0) {
576	      // 随机分配损失
577	      let remaining = accidentLoss;
578	      for (const g of toShip) {
579	        if (remaining <= 0) break;
580	        const loss = Math.min(g.qty, Math.ceil(remaining / toShip.length));
581	        g.qty -= loss;
582	        remaining -= loss;
583	      }
584	      events.push(`🚨 交通事故！约${accidentLoss}件货物损毁。`);
585	      state.needs.happiness = Math.max(0, state.needs.happiness - 15);
586	    }
587	  }
588	
589	  // 4. 力工纠纷事件（仅力工，10%概率）
590	  if (serviceId === "porter" && Random.chance(0.1)) {
591	    const dispute = Random.chance(0.5);
592	    if (dispute) {
593	      // 力工要求加价
594	      const extraCost = Math.round(service.cost * 0.5);
595	      if (state.resources.cash >= extraCost) {
596	        state.resources.cash -= extraCost;
597	        events.push(`😤 力工临时加价，额外支付¥${extraCost}才肯送货。`);
598	        state.needs.happiness = Math.max(0, state.needs.happiness - 5);
599	      } else {
600	        // 付不起，力工扔货走人
601	        for (const g of toShip) {
602	          g.qty = Math.floor(g.qty * 0.5);
603	        }
604	        events.push(
605	          `😤 力工要求加价¥${extraCost}，你付不起，力工扔了一半货走了！`,
606	        );
607	        state.needs.happiness = Math.max(0, state.needs.happiness - 20);
608	      }
609	    } else {
610	      events.push(`😊 力工心情不错，帮你多搬了点。`);
611	    }
612	  }
613	
614	  // 5. 下雨天损货（如果当前有下雨天气）
615	  // 注：天气系统实现后此事件激活
616	  // if (state.weather && state.weather.rainLevel > 1) { ... }
617	
618	  // 到达目的地，将货物放入当地仓库（暂存）
619	  const dest = getLocation(destKey);
620	  if (!state.inventory.storage) state.inventory.storage = {};
621	  if (!state.inventory.storage[destKey]) state.inventory.storage[destKey] = [];
622	
623	  for (const { id, qty, good } of toShip) {
624	    if (qty <= 0) continue;
625	    const existing = state.inventory.storage[destKey].find((i) => i.id === id);
626	    if (existing) {
627	      existing.qty += qty;
628	    } else {
629	      state.inventory.storage[destKey].push({
630	        id,
631	        qty,
632	        avgBuyPrice: getAvgBuyPrice(state, id),
633	      });
634	    }
635	  }
636	
637	  // 反馈信息
638	  const destName = dest ? dest.name : destKey;
639	  StateManager.addMessage(
640	    `🚚 雇佣${service.name}将货物运往${destName}，运费¥${service.cost}。`,
641	    "info",
642	  );
643	
644	  for (const evt of events) {
645	    StateManager.addMessage(evt, evt.includes("😊") ? "success" : "warning");
646	  }
647	
648	  const arrivedQty = toShip.reduce((s, g) => s + g.qty, 0);
649	  if (arrivedQty > 0) {
650	    StateManager.addMessage(
651	      `📦 ${arrivedQty}件货物已到达${destName}，可从当地仓库取出。`,
652	      "success",
653	    );
654	  }
655	
656	  return true;
657	}
