1006	  } else {
1007	    state.inventory.items.push({
1008	      id: goodId,
1009	      qty,
1010	      avgBuyPrice: wholesalePrice,
1011	      buyDay: state.player.day,
1012	    });
1013	  }
1014	
1015	  const enc = calcEncumbrance(state);
1016	  let warnMsg = "";
1017	  if (enc.tier.apPenalty > 0) {
1018	    warnMsg = `（负重${enc.tier.name}，行动+${enc.tier.apPenalty}AP）`;
1019	  }
1020	
1021	  StateManager.addMessage(
1022	    `📦 批发进货${qty}${good.unit}${good.name}，批发价¥${wholesalePrice.toFixed(1)}/件，共¥${totalCost.toFixed(1)}。${warnMsg}`,
1023	    "success",
1024	  );
1025	  return true;
1026	}
1027	
1028	// ====== 覆盖旧版买卖函数 ======
1029	// 使 trade.js 中的函数指向新版
