1	/**
2	 * 天气与气候系统
3	 *
4	 * 设计参考：Don't Starve（四季+温度+理智）、Project Zomboid（雨→感冒+季节）、Stardew Valley（雨影响作物+季节循环）
5	 *
6	 * 核心机制：
7	 * - 四季循环（春→夏→秋→冬，每季30天）
8	 * - 温度系统（影响健康、体感、衣物需求）
9	 * - 天气类型（晴/多云/阴/小雨/大雨/暴雨/雷暴/小雪/大雪/暴雪/雾/沙尘暴/台风）
10	 * - 天气对游戏的影响：AP消耗、交易价格、运输风险、健康/心情、随机事件触发
11	 */
12	
13	// ====== 季节定义 ======
14	const SEASONS = {
15	  spring: {
16	    name: "春",
17	    icon: "🌸",
18	    tempRange: [8, 22],
19	    daysPerSeason: 30,
20	    desc: "万物复苏，偶有春雨",
21	  },
22	  summer: {
23	    name: "夏",
24	    icon: "☀️",
25	    tempRange: [25, 38],
26	    daysPerSeason: 30,
27	    desc: "酷暑难耐，时有暴雨台风",
28	  },
29	  autumn: {
30	    name: "秋",
31	    icon: "🍂",
32	    tempRange: [10, 25],
33	    daysPerSeason: 30,
34	    desc: "秋高气爽，偶有秋雨大雾",
35	  },
36	  winter: {
37	    name: "冬",
38	    icon: "❄️",
39	    tempRange: [-8, 8],
40	    daysPerSeason: 30,
41	    desc: "天寒地冻，时有风雪",
42	  },
43	};
44	
45	const SEASON_ORDER = ["spring", "summer", "autumn", "winter"];
46	
47	/** 根据天数获取当前季节 */
48	function getSeason(day) {
49	  const yearDay = (day - 1) % 120; // 120天 = 1年
50	  const seasonIdx = Math.floor(yearDay / 30);
51	  return SEASON_ORDER[Math.min(seasonIdx, 3)];
52	}
53	
54	/** 获取季节内的天数（1-30） */
55	function getSeasonDay(day) {
56	  return ((day - 1) % 30) + 1;
57	}
58	
59	/** 获取年份 */
60	function getYear(day) {
61	  return Math.floor((day - 1) / 120) + 1;
62	}
63	
64	// ====== 天气类型定义 ======
65	const WEATHER_TYPES = {
66	  sunny: {
67	    name: "晴",
68	    icon: "☀️",
69	    apMod: 0,
70	    priceMod: 1.0,
71	    transportRisk: 0,
72	    moodMod: 3,
73	    fatigueMod: 0,
74	    healthMod: 0,
75	    tempMod: 2,
76	    visible: true,
77	  },
78	  partly_cloudy: {
79	    name: "多云",
80	    icon: "⛅",
81	    apMod: 0,
82	    priceMod: 1.0,
83	    transportRisk: 0,
84	    moodMod: 0,
85	    fatigueMod: 0,
86	    healthMod: 0,
87	    tempMod: 0,
88	    visible: true,
89	  },
90	  cloudy: {
91	    name: "阴",
92	    icon: "☁️",
93	    apMod: 0,
94	    priceMod: 1.0,
95	    transportRisk: 0,
96	    moodMod: -2,
97	    fatigueMod: 0,
98	    healthMod: 0,
99	    tempMod: -1,
100	    visible: true,
