382	/** 根据季节和随机数生成天气（加权随机选择天气类型） */
383	function generateWeather(season) {
384	  const probs = SEASON_WEATHER_PROBS[season];
385	  if (!probs) return "sunny";
386	
387	  const entries = Object.entries(probs);
388	  const result = Random.weighted(entries, (e) => e[1]);
389	  return result ? result[0] : "sunny";
390	}
