392	/** 根据季节和天气生成温度 */
393	function generateTemperature(season, weatherId) {
394	  const seasonDef = SEASONS[season];
395	  const [minT, maxT] = seasonDef.tempRange;
396	  const weatherDef = WEATHER_TYPES[weatherId];
397	
398	  // 基础温度在季节范围内随机
399	  let temp = minT + Random.float(0, maxT - minT);
400	
401	  // 天气对温度的影响
402	  temp += weatherDef.tempMod;
403	
404	  // 昼夜温差（上午偏暖+2，晚上偏凉-3）
405	  // 注意：这里只返回基础温度，昼夜调整在 tick 时根据时段做
406	
407	  return Math.round(temp * 10) / 10;
408	}
