410	/** 初始化天气状态（新游戏或新的一天） */
411	function initWeatherState(state) {
412	  if (!state.weather) {
413	    state.weather = {};
414	  }
415	
416	  const season = getSeason(state.player.day);
417	  const weatherId = generateWeather(season);
418	  const temperature = generateTemperature(season, weatherId);
419	
420	  // 连续性：30%概率延续昨天的天气
421	  if (state.weather.weatherId && Random.chance(0.3)) {
422	    // 延续昨日天气，但温度微调
423	    state.weather.temperature =
424	      Math.round((state.weather.temperature + Random.float(-1.5, 1.5)) * 10) /
425	      10;
426	  } else {
427	    state.weather.weatherId = weatherId;
428	    state.weather.temperature = temperature;
429	  }
430	
431	  state.weather.season = season;
432	  state.weather.seasonDay = getSeasonDay(state.player.day);
433	  state.weather.year = getYear(state.player.day);
434	
435	  // 根据时段调整温度
436	  adjustTempForTimeSlot(state);
437	
438	  // 缓存天气定义
439	  state.weather.weatherDef =
440	    WEATHER_TYPES[state.weather.weatherId] || WEATHER_TYPES.sunny;
441	  state.weather.tempEffect = getTempEffect(state.weather.temperature);
442	}
