634	/** 计算并应用舒适度影响 */
635	function applyComfortEffects(state) {
636	  if (!state.status) return;
637	
638	  let comfort = 50; // 基础舒适度
639	
640	  // 住所加成
641	  const housingBonus = [0, 10, 20, 35][state.housing?.tier || 0];
642	  comfort += housingBonus;
643	
644	  // 衣物加成（身体装备位）
645	  const bodyEquip = state.inventory?.equipment?.body;
646	  if (bodyEquip && typeof ITEMS !== "undefined") {
647	    const item = ITEMS.find((i) => i.id === bodyEquip);
648	    if (item && item.effects) {
649	      if (item.effects.comfort) comfort += item.effects.comfort;
650	    }
651	  }
652	
653	  // 天气对舒适度的影响
654	  if (state.weather && state.weather.tempEffect) {
655	    const tempName = state.weather.tempEffect.name;
656	    if (tempName === "酷热") comfort -= 20;
657	    else if (tempName === "炎热") comfort -= 10;
658	    else if (tempName === "温暖") comfort += 10;
659	    else if (tempName === "凉爽") comfort += 5;
660	    else if (tempName === "寒冷") comfort -= 10;
661	    else if (tempName === "严寒") comfort -= 20;
662	    else if (tempName === "极寒") comfort -= 30;
663	  }
664	
665	  // 卫生影响舒适度
666	  if (state.needs?.hygiene < 30) comfort -= 15;
667	  else if (state.needs?.hygiene < 60) comfort -= 5;
668	
669	  // 限制范围
670	  comfort = Math.max(0, Math.min(100, comfort));
671	  state.status.comfort = comfort;
672	
673	  // 舒适度对心情的影响
674	  if (comfort < 20) {
675	    state.needs.happiness = Math.max(0, state.needs.happiness - 5);
676	  } else if (comfort < 40) {
677	    state.needs.happiness = Math.max(0, state.needs.happiness - 2);
678	  } else if (comfort > 80) {
679	    state.needs.happiness = Math.min(100, state.needs.happiness + 2);
680	  }
681	}
