685	  let coldProtection = 0; // 防寒值
686	  let heatProtection = 0; // 防暑值
687	
688	  // 检查所有装备位的衣物
689	  const equip = state.inventory?.equipment || {};
690	  for (const [slot, itemId] of Object.entries(equip)) {
691	    if (!itemId || typeof ITEMS === "undefined") continue;
692	    const item = ITEMS.find((i) => i.id === itemId);
693	    if (!item || !item.effects) continue;
694	    coldProtection += item.effects.coldProtection || 0;
695	    heatProtection += item.effects.heatProtection || 0;
696	  }
697	
698	  return { coldProtection, heatProtection };
699	}
700	
701	/** 计算天气+衣物对健康的综合影响（考虑防护后） */
702	function getNetWeatherHealthImpact(state) {
703	  if (!state.weather || !state.weather.tempEffect) return 0;
704	
705	  const tempEffect = state.weather.tempEffect;
706	  const weatherDef = state.weather.weatherDef;
707	  const protection = getClothingWeatherProtection(state);
708	
709	  let healthImpact = (weatherDef?.healthMod || 0) + (tempEffect.healthMod || 0);
710	
711	  // 防寒效果：寒冷/严寒/极寒时减少健康损失
712	  if (tempEffect.minTemp < 8) {
713	    const coldReduction = Math.min(
714	      protection.coldProtection,
715	      Math.abs(tempEffect.healthMod),
716	    );
717	    healthImpact += coldReduction; // 抵消部分健康损失
718	  }
719	
720	  // 防暑效果：酷热/炎热时减少健康损失
721	  if (tempEffect.minTemp >= 32) {
722	    const heatReduction = Math.min(
723	      protection.heatProtection,
724	      Math.abs(tempEffect.healthMod),
725	    );
726	    healthImpact += heatReduction;
727	  }
728	
729	  return healthImpact;
730	}
731	
732	/** 获取天气描述文本 */
733	function getWeatherDescription(state) {
734	  if (!state.weather) return "未知";
735	
736	  const w = state.weather.weatherDef;
737	  const t = state.weather.tempEffect;
738	  const s = SEASONS[state.weather.season];
739	
740	  let desc = `${s.icon} ${s.name}季 · ${w.icon} ${w.name} · 🌡️ ${state.weather.temperature}°C（${t.name}）`;
741	
742	  // 天气影响提示
743	  const effects = [];
744	  if (w.apMod > 0) effects.push(`出行+${w.apMod}AP`);
745	  if (w.priceMod !== 1.0)
746	    effects.push(w.priceMod < 1 ? "物价下降" : "物价上涨");
747	  if (w.moodMod < -3) effects.push("心情变差");
748	  if (w.transportRisk > 1.1) effects.push("运输风险增加");
749	  if (!w.visible) effects.push("⚠️不宜出行");
750	
751	  // 客流量提示
752	  const trafficMod = getWeatherFootTrafficModifier(state);
753	  if (trafficMod < 0.8)
754	    effects.push(`🚶客流量低(${Math.round(trafficMod * 100)}%)`);
755	  else if (trafficMod > 1.0) effects.push("🚶客流量高");
756	
757	  if (effects.length > 0) {
758	    desc += `\n${effects.join(" | ")}`;
759	  }
760	
761	  return desc;
762	}
763	
764	/** 获取天气对特定商品的价格影响 */
765	function getWeatherGoodPriceMod(state, goodId) {
766	  if (!state.weather) return 1.0;
767	
768	  const baseMod = getWeatherPriceModifier(state);
769	  let extraMod = 1.0;
770	
771	  const phys =
772	    typeof getGoodPhysics === "function" ? getGoodPhysics(goodId) : null;
773	
774	  // 下雨天：雨具/日常用品需求增加
775	  if (
776	    state.weather.weatherId === "heavy_rain" ||
777	    state.weather.weatherId === "thunderstorm" ||
778	    state.weather.weatherId === "typhoon"
779	  ) {
780	    if (goodId === "daily_use") extraMod = 1.15; // 日用品需求涨
781	    if (goodId === "cigarettes") extraMod = 1.1; // 烟也需求涨（无聊待家里）
782	  }
783	
784	  // 热浪：水和饮料需求增加
785	  if (state.weather.weatherId === "heatwave") {
786	    if (goodId === "water" || goodId === "beer") extraMod = 1.2;
787	    if (goodId === "fruits") extraMod = 1.1;
788	  }
789	
790	  // 寒潮：保暖品需求增加
791	  if (
792	    state.weather.weatherId === "cold_snap" ||
793	    state.weather.weatherId === "blizzard"
794	  ) {
795	    if (goodId === "clothing") extraMod = 1.2;
796	    if (goodId === "instant_noodles") extraMod = 1.15;
797	  }
798	
799	  // 暴雪：所有商品运输困难，价格普涨
800	  if (state.weather.weatherId === "blizzard") {
801	    extraMod *= 1.1;
802	  }
803	
804	  // 沙尘暴：易损商品（电子产品）风险
805	  if (state.weather.weatherId === "sandstorm") {
806	    if (goodId === "electronics") extraMod = 0.9; // 电子产品可能进沙
807	  }
808	
809	  return Math.round(baseMod * extraMod * 100) / 100;
810	}
