          return (
            "<p>🍳 当前收录 <b>" +
            n +
            "</b> 种食谱（Lv.1-Lv.10）。前往 " +
            _wkLink("items", null, "🎒 物品/食材") +
            " 查看可用食材。</p>"
          );
        },
      },
      { kind: "subhead", text: "📊 食材分类" },
      {
        kind: "list",
        items: [
          "主食类：大米、面粉、面条、土豆",
          "蔬菜类：青菜、白菜、萝卜、番茄、黄瓜",
          "肉类：猪肉、牛肉、鸡肉、鱼",
          "调料类：盐、酱油、油、糖、辣椒",
          "蛋奶类：鸡蛋、牛奶",
        ],
      },
      { kind: "subhead", text: "🔄 食材保鲜" },
      {
        kind: "list",
        items: [
          "常温：按 perishDays 标注的天数",
          "冰箱（自住房）：+5天",
          "冷冻（自住房）：+15天",
        ],
      },
      { kind: "subhead", text: "💡 提示" },
      {
        kind: "tip",
        text: "在家做饭（amenity）会消耗食材。烹饪技能越高，解锁的食谱越强力。",
      },
    ],
  };
}

