const TEMP_EFFECTS = [
  { name: "酷热", minTemp: 38, maxTemp: 99, fatigueMod: 5, healthMod: -3, moodMod: -8, desc: "中暑风险极高" },
  { name: "炎热", minTemp: 32, maxTemp: 38, fatigueMod: 3, healthMod: -1, moodMod: -4, desc: "汗如雨下" },
  { name: "温暖", minTemp: 18, maxTemp: 32, fatigueMod: 0, healthMod: 0,  moodMod: 2,  desc: "体感舒适" },
  { name: "凉爽", minTemp: 8,  maxTemp: 18, fatigueMod: 0, healthMod: 0,  moodMod: 1,  desc: "微凉" },
  { name: "寒冷", minTemp: 0,  maxTemp: 8,  fatigueMod: 2, healthMod: -1, moodMod: -3, desc: "冻手冻脚" },
  { name: "严寒", minTemp: -8, maxTemp: 0,  fatigueMod: 4, healthMod: -2, moodMod: -6, desc: "刺骨寒冷" },
  { name: "极寒", minTemp: -99,maxTemp: -8, fatigueMod: 6, healthMod: -4, moodMod: -10,desc: "随时冻伤" },
];

/** 获取温度体感效果 */
function getTempEffect(temperature) {
  for (var i = 0; i < TEMP_EFFECTS.length; i++) {
    if (temperature >= TEMP_EFFECTS[i].minTemp && temperature < TEMP_EFFECTS[i].maxTemp) return TEMP_EFFECTS[i];
  }
  return TEMP_EFFECTS[3]; // 默认凉爽
}

/** 获取衣物对极端天气的防护效果（从装备 items 读取 coldProtection/heatProtection） */
function getClothingWeatherProtection(state) {
  var cold = 0, heat = 0;
  var equip = state.inventory && state.inventory.equipment ? state.inventory.equipment : {};
  for (var slot in equip) {
    if (!equip.hasOwnProperty(slot)) continue;
    var itemId = equip[slot];
    if (!itemId || typeof ITEMS === "undefined") continue;
    var item = ITEMS.find(function(i) { return i.id === itemId; });
    if (item && item.effects) {
      cold += item.effects.coldProtection || 0;
      heat += item.effects.heatProtection || 0;
    }
  }
  return { coldProtection: cold, heatProtection: heat };
}

/** 计算天气+衣物的综合健康影响 */
function getNetWeatherHealthImpact(state) {
  if (!state.weather || !state.weather.current) return 0;
  var wDef = WEATHER_TYPES.find(function(w) { return w.id === state.weather.current; });
  var protection = getClothingWeatherProtection(state);
  var tempEffect = getTempEffect(state.weather.temperature || 22);
  var base = tempEffect.healthMod;
  // 防寒
  if (tempEffect.minTemp < 8) base += Math.min(protection.coldProtection, Math.abs(tempEffect.healthMod));
  // 防暑
  if (tempEffect.minTemp >= 32) base += Math.min(protection.heatProtection, Math.abs(tempEffect.healthMod));
  return base;
}

/** 每日结算天气对属性影响（在 daily_pipeline 中调用） */
function applyWeatherDailyEffects(state) {
  if (!state.weather) return;
  var wDef = WEATHER_TYPES.find(function(w) { return w.id === state.weather.current; }) || WEATHER_TYPES[0];
  var tempEffect = getTempEffect(state.weather.temperature || 22);

  // 天气对心情
  state.needs.happiness = Math.max(0, Math.min(100, state.needs.happiness + (wDef.happinessBonus || 0) + (tempEffect.moodMod || 0)));
  // 天气对疲劳
  state.needs.fatigue = Math.max(0, Math.min(100, state.needs.fatigue + (wDef.fatigueBonus || 0) + (tempEffect.fatigueMod || 0)));
  // 天气对健康
  if (state.status && state.status.health !== undefined) {
    state.status.health = Math.max(0, Math.min(100, state.status.health + (tempEffect.healthMod || 0)));
  }

  // 极端场景提示
  var wId = state.weather.current;
  if (wId === "stormy" && Random.chance(0.15)) StateManager.addMessage("⚡ 雷雨交加，不宜外出！", "danger");
  if (wId === "snowy" && Random.chance(0.2)) StateManager.addMessage("❄️ 大雪纷飞，行动不便！", "warning");

  // 舒适度计算
  if (!state.status) state.status = {};
  var comfort = 50 + ((state.housing && state.housing.tier) || 0) * 10;
  if (tempEffect.name === "酷热") comfort -= 20;
  else if (tempEffect.name === "炎热") comfort -= 10;
  else if (tempEffect.name === "温暖") comfort += 10;
  else if (tempEffect.name === "凉爽") comfort += 5;
  else if (tempEffect.name === "寒冷") comfort -= 10;
  else if (tempEffect.name === "严寒") comfort -= 20;
  else if (tempEffect.name === "极寒") comfort -= 30;
  if (state.needs.hygiene < 30) comfort -= 15;
  else if (state.needs.hygiene < 60) comfort -= 5;
  comfort = Math.max(0, Math.min(100, comfort));
  state.status.comfort = comfort;

  if (comfort < 20) state.needs.happiness = Math.max(0, state.needs.happiness - 5);
  else if (comfort < 40) state.needs.happiness = Math.max(0, state.needs.happiness - 2);
  else if (comfort > 80) state.needs.happiness = Math.min(100, state.needs.happiness + 2);
}

/** 获取天气对特定商品的价格影响（风/雨/雪天某些商品涨价） */
function getWeatherGoodPriceMod(state, goodId) {
  if (!state.weather) return 1.0;
  var base = 1.0;
  var wId = state.weather.current;
  if (wId === "rainy" || wId === "stormy") {
    if (goodId === "daily_use") base = 1.15;
    if (goodId === "cigarettes") base = 1.1;
  }
  if (wId === "snowy") {
    if (goodId === "clothing") base = 1.2;
    if (goodId === "instant_noodles") base = 1.15;
  }
  if (wId === "windy") {
    if (goodId === "clothing") base = 1.1;
  }
  return base;
}

/** 获取天气对运输风险的修正（>1 = 风险增加） */
function getWeatherTransportRiskMod(state) {
  if (!state.weather) return 1.0;
  var riskMap = {
    rainy: 1.05, stormy: 1.15, windy: 1.1, snowy: 1.3, foggy: 1.1
  };
  return riskMap[state.weather.current] || 1.0;
}

/** 天气是否不宜出行 */
function isWeatherTravelBlocked(state) {
  if (!state.weather) return false;
  return state.weather.current === "stormy" || state.weather.current === "snowy";
}

/** 获取天气详细描述文本 */
function getWeatherEnhancedDesc(state) {
  if (!state.weather) return "未知";
  var wDef = WEATHER_TYPES.find(function(w) { return w.id === state.weather.current; }) || WEATHER_TYPES[0];
  var tempEffect = getTempEffect(state.weather.temperature || 22);
  var parts = [wDef.icon + " " + wDef.name, "🌡️ " + (state.weather.temperature || "?") + "°C（" + tempEffect.name + "）"];
  if (wDef.happinessBonus < -3) parts.push("☹️心情差");
  if (wDef.fatigueBonus > 5) parts.push("😰易疲劳");
  if (tempEffect.healthMod < -2) parts.push("⚠️影响健康");
  return parts.join(" · ");
}

