588	          items.splice(i, 1);
589	        }
590	      }
591	      if (spoiled.length > 0) {
592	        var msg = "🥀 食材过期：";
593	        for (var si = 0; si < spoiled.length; si++) {
594	          msg +=
595	            spoiled[si].icon + spoiled[si].name + "×" + spoiled[si].qty + " ";
596	        }
597	        StateManager.addMessage(msg + "已变质扔掉。", "warning");
598	      }
599	    },
600	  },
601	
602	  // === 每日收支报告（阻塞弹窗）===
603	  {
604	    name: "daily_report",
605	    fn: function (state) {
606	      if (typeof showDailyReport === "function") {
607	        showDailyReport(state);
608	      }
609	    },
610	  },
611	
612	  // === NPC桥接（事件后NPC回响 + 日常互动）===
613	  {
614	    name: "npc_bridge",
615	    fn: function (state) {
616	      if (typeof runDailyNpcBridge === "function") {
617	        runDailyNpcBridge(state);
618	      }
619	    },
620	  },
621	
622	  // === 道德后果检查 ===
623	  {
624	    name: "moral_consequences",
625	    fn: function (state) {
626	      if (typeof checkMoralConsequences === "function") {
627	        checkMoralConsequences(state);
628	      }
629	    },
630	  },
631	
632	  // === 新闻桥接（新闻→事件权重 + 价格情绪）===
633	  {
634	    name: "news_bridge",
635	    fn: function (state) {
636	      if (typeof runDailyNewsBridge === "function") {
637	        runDailyNewsBridge(state);
638	      }
639	    },
640	  },
641	];
642	
643	/** 生成每日一句话总结 */
644	function generateDailySummary(state, startCash, startHealth, startHappiness) {
645	  var cash = state.resources.cash || 0;
646	  var bank = state.resources.bankBalance || 0;
647	  var delta = cash - startCash;
648	  var healthDrop = startHealth - ((state.status && state.status.health) || 100);
649	  var happyDrop =
650	    startHappiness - ((state.needs && state.needs.happiness) || 0);
651	  var day = state.player.day || 1;
652	
653	  var highlights = [];
654	
655	  // 特殊叙事片段（优先级最高）
656	  if (state.flags._todayDeepTaskDone) {
657	    highlights.push("有个人在你心里留下了什么");
658	  } else if (state.flags._todayDebtEvent) {
659	    highlights.push("村长的钱，又压了一整天");
660	  } else if (state.flags._todayMentalEvent) {
661	    highlights.push("心里那根弦今天绷得很紧");
662	  }
663	
664	  // 财务总结（分更多档次，语气有温度）
665	  if (delta >= 1000) {
666	    highlights.push("今天是个好日子，净赚了¥" + delta.toLocaleString());
667	  } else if (delta >= 300) {
668	    highlights.push("今天赚了¥" + delta.toLocaleString() + "，还不错");
669	  } else if (delta >= 50) {
670	    highlights.push("今天净入¥" + delta.toLocaleString() + "，比昨天强点");
671	  } else if (delta >= 0) {
672	    highlights.push("今天收支基本持平，活下来了");
673	  } else if (delta < -500) {
674	    highlights.push("今天支出不少，净亏了¥" + Math.abs(delta).toLocaleString());
675	  } else if (delta < 0) {
676	    highlights.push(
677	      "今天支出略多，口袋瘦了¥" + Math.abs(delta).toLocaleString(),
678	    );
679	  }
680	
681	  // 里程碑叙事
682	  if (day === 7) highlights.push("来这座城市整整一周了");
683	  else if (day === 30) highlights.push("整整一个月，你还在");
684	  else if (day === 100) highlights.push("百天了，城市没把你打倒");
685	  else if (day === 365) highlights.push("一年了，从头到今天");
686	
687	  // 存款鼓励
688	  if (bank >= 10000 && highlights.length < 2) {
689	    highlights.push("银行里¥" + bank.toLocaleString() + "，是你在这城市的底气");
690	  } else if (bank > 0 && highlights.length < 2) {
691	    highlights.push("银行里的¥" + bank.toLocaleString() + "还在生息");
692	  }
693	
694	  // 健康/心情状态
695	  if (healthDrop >= 15) {
696	    highlights.push("身体吃不消了，明天注意");
697	  } else if (happyDrop >= 20) {
698	    highlights.push("今天过得不太开心，明天找找乐子");
699	  }
700	
701	  // 村长债务提示（仅经典模式/有 villageDebt 的剧本）
702	  if ((state.resources.villageDebt || 0) > 0 && highlights.length < 2) {
703	    highlights.push(
704	      "村长那¥" +
705	        (state.resources.villageDebt || 0).toLocaleString() +
706	        "的债还压着呢",
707	    );
708	  }
709	
710	  // 节日氛围
711	  if (typeof getCurrentFestival === "function") {
712	    var fest = getCurrentFestival(day);
713	    if (fest && highlights.length < 2)
714	      highlights.push(fest.icon + " " + fest.name + "的气氛越来越浓了");
715	  }
716	
717	  // 梦想进度
718	  if (typeof getDreamProgress === "function" && highlights.length < 2) {
719	    var dp = getDreamProgress(state);
720	    if (dp > 0 && dp < 100) highlights.push("梦想进度" + dp + "%，一直往前");
721	  }
722	
723	  // 清除今日临时标记
724	  delete state.flags._todayDeepTaskDone;
725	  delete state.flags._todayDebtEvent;
726	  delete state.flags._todayMentalEvent;
727	
728	  if (!highlights.length) highlights.push("平凡的一天，活着就是赢了");
729	
730	  var summary = highlights.slice(0, 2).join("，") + "。";
731	  return "📋 今日总结：" + summary;
732	}
733	
734	/**
735	 * 执行每日结算管线。
736	 * 遍历所有步骤，遇到极端状态('skip_day')时短路。
737	 * MiniMax 友好：新增步骤只需 push 一个 {name, fn} 对象。
738	 */
739	function runDailyPipeline(state) {
740	  // 记录日始状态用于今日总结（存入 state.flags 供 end_log fn 读取）
741	  state.flags._dayStartCash = state.resources.cash || 0;
742	  state.flags._dayStartHealth = (state.status && state.status.health) || 100;
743	  state.flags._dayStartHappiness = (state.needs && state.needs.happiness) || 0;
744	
745	  for (var i = 0; i < DAILY_PIPELINE.length; i++) {
746	    var step = DAILY_PIPELINE[i];
747	
748	    // 极端状态短路逻辑：
749	    // extreme_check / critical_punish 返回 'skip_day' 时，跳过后续非核心步骤
750	    // 但 finance / autosave 始终执行（保证利息和存档不丢）
751	    if (step.name === "extreme_check" || step.name === "critical_punish") {
752	      var result = step.fn(state);
753	      if (result === "skip_day") {
754	        StateManager.addMessage(
755	          "🌙 第" + state.player.day + "天在昏迷中过去了...",
756	          "danger",
757	        );
758	        // 执行最后的核心步骤：财务、存档
759	        for (var j = i + 1; j < DAILY_PIPELINE.length; j++) {
760	          var lateStep = DAILY_PIPELINE[j];
761	          if (lateStep.name === "finance" || lateStep.name === "autosave") {
762	            lateStep.fn(state);
763	          }
764	        }
765	        return; // 短路
766	      }
767	    } else {
768	      step.fn(state);
769	    }
770	  }
771	}
772	
773	/**
774	 * endDay — 仅保留管线调度逻辑（MiniMax 友好：170行→8行）
775	 */
776	function endDay() {
777	  var state = StateManager.getState();
778	  runDailyPipeline(state);
779	}
